// Extension d'essai du panneau (protocole 1.0, lot 4) : un relevé du dessin, tenu à jour dans la page du panneau.
const etat = async () => {
  const m = await planche.modele.lire();
  return { aretes: m.aretes.length, faces: m.faces.length };
};
// Actions nommées, appelées par la page (fadi.action).
planche.panneau.sur("releve", "etat", etat);
planche.panneau.sur("releve", "tracer", async (d) => {
  const longueur = Number(String(d && d.longueur).replace(",", "."));
  if (!Number.isFinite(longueur) || longueur <= 0) throw new Error(d && d.langue === "en" ? "Enter a length greater than zero." : "Indiquez une longueur supérieure à zéro.");
  await planche.modele.ligne([0, 0, 0], [longueur, 0, 0]);
  return etat();
});
// Le dessin change (geste de l'utilisateur, annulation) : la page reçoit le nouveau relevé.
planche.sur("modele.change", async () => {
  await planche.panneau.envoyer("releve", await etat());
});
planche.sur("commande.ouvrir-releve", () => planche.panneau.ouvrir("releve"));

