(function () {
  var en = fadi.langue === "en";
  var element = function (id) { return document.getElementById(id); };
  element("titre-trace").textContent = en ? "Draw a line" : "Tracer une ligne";
  element("libelle-longueur").textContent = en ? "Length (m)" : "Longueur (m)";
  element("tracer").textContent = en ? "Draw from the origin" : "Tracer depuis l'origine";
  element("titre-releve").textContent = en ? "In this drawing" : "Dans ce dessin";
  element("libelle-aretes").textContent = en ? "Edges" : "Arêtes";
  element("libelle-faces").textContent = "Faces";
  var montrer = function (e) {
    if (!e) return;
    element("aretes").textContent = String(e.aretes);
    element("faces").textContent = String(e.faces);
  };
  // Données envoyées par l'extension quand le dessin change.
  fadi.surDonnees(montrer);
  fadi.action("etat").then(montrer);
  element("tracer").addEventListener("click", function () {
    element("erreur").hidden = true;
    fadi.action("tracer", { longueur: element("longueur").value, langue: fadi.langue }).then(montrer, function (e) {
      element("erreur").textContent = e.message;
      element("erreur").hidden = false;
    });
  });
})();
